`timescale 1ns/1ps

// phase3_axi_dma_wrapper_smoke_tb — P3-14A
// Smoke-level compile + basic-function testbench for phase3_sync_axis_dma_wrapper.
//
// Checks:
//   1. Reset exits cleanly (no X on AXI-Lite outputs)
//   2. AXI-Lite VERSION read returns 0x00316001
//   3. AXI-Lite CONTROL write sets enable (read-back check)
//   4. S_AXIS tready is not X after reset
//   5. M_AXIS tvalid is not X after reset
//
// Uses a low THRESHOLD (40000) so frame detection would trigger on the
// amplitude-3000 stimulus generated by gen_phase3_iq_stimulus.py.
// However, this smoke test does NOT run full frame detection — it exits
// after 500 cycles.
//
// Simulator: iverilog -g2012 or xsim.
// Pass: simulation reaches $finish without triggering any FAIL check.

module phase3_axi_dma_wrapper_smoke_tb;

    // -----------------------------------------------------------------------
    // Parameters
    // -----------------------------------------------------------------------
    localparam integer IQ_WIDTH        = 16;
    localparam integer NSC             = 256;
    localparam integer CP_LEN          = 32;
    localparam integer BUF_AW          = 12;
    localparam integer ENERGY_WIDTH    = 40;
    localparam integer NCO_PHASE_WIDTH = 32;
    localparam integer PHASE_WIDTH     = 16;
    localparam integer INDEX_WIDTH     = 9;

    // Low threshold for smoke-level stimulus (amplitude 3000 signal)
    localparam integer THRESHOLD_SMOKE = 40000;

    localparam [31:0] EXPECTED_VERSION = 32'h00316001;

    // AXI-Lite addresses
    localparam [6:0] ADDR_VERSION  = 7'h00;
    localparam [6:0] ADDR_CONTROL  = 7'h04;
    localparam [6:0] ADDR_STATUS   = 7'h08;

    // -----------------------------------------------------------------------
    // Clock and reset
    // -----------------------------------------------------------------------
    reg aclk;
    reg aresetn;

    initial aclk = 1'b0;
    always #5 aclk = ~aclk;   // 100 MHz

    // -----------------------------------------------------------------------
    // AXI-Lite master signals
    // -----------------------------------------------------------------------
    reg  [6:0]  m_axi_awaddr;
    reg         m_axi_awvalid;
    wire        m_axi_awready;
    reg  [31:0] m_axi_wdata;
    reg  [3:0]  m_axi_wstrb;
    reg         m_axi_wvalid;
    wire        m_axi_wready;
    wire [1:0]  m_axi_bresp;
    wire        m_axi_bvalid;
    reg         m_axi_bready;
    reg  [6:0]  m_axi_araddr;
    reg         m_axi_arvalid;
    wire        m_axi_arready;
    wire [31:0] m_axi_rdata;
    wire [1:0]  m_axi_rresp;
    wire        m_axi_rvalid;
    reg         m_axi_rready;

    // -----------------------------------------------------------------------
    // AXI-Stream slave (stimulus → DUT S_AXIS)
    // -----------------------------------------------------------------------
    reg  [2*IQ_WIDTH-1:0] s_axis_tdata;
    reg                   s_axis_tvalid;
    wire                  s_axis_tready;
    reg                   s_axis_tlast;

    // AXI-Stream master (DUT M_AXIS → sink)
    wire [2*IQ_WIDTH-1:0] m_axis_tdata;
    wire                  m_axis_tvalid;
    reg                   m_axis_tready;
    wire                  m_axis_tlast;

    // -----------------------------------------------------------------------
    // DUT instantiation
    // -----------------------------------------------------------------------
    phase3_sync_axis_dma_wrapper #(
        .IQ_WIDTH        (IQ_WIDTH),
        .NSC             (NSC),
        .CP_LEN          (CP_LEN),
        .BUF_AW          (BUF_AW),
        .THRESHOLD       (THRESHOLD_SMOKE),
        .NCO_PHASE_WIDTH (NCO_PHASE_WIDTH)
    ) u_dut (
        .aclk            (aclk),
        .aresetn         (aresetn),

        .s_axi_awaddr    (m_axi_awaddr),
        .s_axi_awvalid   (m_axi_awvalid),
        .s_axi_awready   (m_axi_awready),
        .s_axi_wdata     (m_axi_wdata),
        .s_axi_wstrb     (m_axi_wstrb),
        .s_axi_wvalid    (m_axi_wvalid),
        .s_axi_wready    (m_axi_wready),
        .s_axi_bresp     (m_axi_bresp),
        .s_axi_bvalid    (m_axi_bvalid),
        .s_axi_bready    (m_axi_bready),
        .s_axi_araddr    (m_axi_araddr),
        .s_axi_arvalid   (m_axi_arvalid),
        .s_axi_arready   (m_axi_arready),
        .s_axi_rdata     (m_axi_rdata),
        .s_axi_rresp     (m_axi_rresp),
        .s_axi_rvalid    (m_axi_rvalid),
        .s_axi_rready    (m_axi_rready),

        .s_axis_tdata    (s_axis_tdata),
        .s_axis_tvalid   (s_axis_tvalid),
        .s_axis_tready   (s_axis_tready),
        .s_axis_tlast    (s_axis_tlast),

        .m_axis_tdata    (m_axis_tdata),
        .m_axis_tvalid   (m_axis_tvalid),
        .m_axis_tready   (m_axis_tready),
        .m_axis_tlast    (m_axis_tlast)
    );

    // -----------------------------------------------------------------------
    // AXI-Lite task: read a register
    // -----------------------------------------------------------------------
    reg [31:0] axi_rd_data;
    reg [1:0]  axi_rd_resp;

    task axi_read;
        input [6:0] addr;
        begin
            @(posedge aclk);
            m_axi_araddr  = addr;
            m_axi_arvalid = 1'b1;
            m_axi_rready  = 1'b1;
            // Wait for arready
            while (!m_axi_arready) @(posedge aclk);
            @(posedge aclk);
            m_axi_arvalid = 1'b0;
            // Wait for rvalid
            while (!m_axi_rvalid) @(posedge aclk);
            axi_rd_data = m_axi_rdata;
            axi_rd_resp = m_axi_rresp;
            @(posedge aclk);
            m_axi_rready = 1'b0;
        end
    endtask

    // -----------------------------------------------------------------------
    // AXI-Lite task: write a register
    // -----------------------------------------------------------------------
    task axi_write;
        input [6:0]  addr;
        input [31:0] data;
        begin
            @(posedge aclk);
            m_axi_awaddr  = addr;
            m_axi_awvalid = 1'b1;
            m_axi_wdata   = data;
            m_axi_wstrb   = 4'hF;
            m_axi_wvalid  = 1'b1;
            m_axi_bready  = 1'b1;
            // Wait for both channels accepted
            while (!(m_axi_awready && m_axi_wready)) @(posedge aclk);
            @(posedge aclk);
            m_axi_awvalid = 1'b0;
            m_axi_wvalid  = 1'b0;
            // Wait for bvalid
            while (!m_axi_bvalid) @(posedge aclk);
            @(posedge aclk);
            m_axi_bready = 1'b0;
        end
    endtask

    // -----------------------------------------------------------------------
    // Waveform dump
    // -----------------------------------------------------------------------
    initial begin
        $dumpfile("logs/p3_14a_smoke_sim.vcd");
        $dumpvars(0, phase3_axi_dma_wrapper_smoke_tb);
    end

    // -----------------------------------------------------------------------
    // Watchdog
    // -----------------------------------------------------------------------
    integer cycle_cnt;
    initial begin
        cycle_cnt = 0;
        forever begin
            @(posedge aclk);
            cycle_cnt = cycle_cnt + 1;
            if (cycle_cnt > 5000) begin
                $display("FAIL: watchdog expired at %0t ns", $time);
                $finish;
            end
        end
    end

    // -----------------------------------------------------------------------
    // Main test sequence
    // -----------------------------------------------------------------------
    integer i;
    integer fail_count;

    initial begin
        fail_count = 0;

        // Initialise AXI-Lite master
        m_axi_awaddr  = 7'h00;
        m_axi_awvalid = 1'b0;
        m_axi_wdata   = 32'h0;
        m_axi_wstrb   = 4'h0;
        m_axi_wvalid  = 1'b0;
        m_axi_bready  = 1'b0;
        m_axi_araddr  = 7'h00;
        m_axi_arvalid = 1'b0;
        m_axi_rready  = 1'b0;

        // S_AXIS driven idle
        s_axis_tdata  = {(2*IQ_WIDTH){1'b0}};
        s_axis_tvalid = 1'b0;
        s_axis_tlast  = 1'b0;

        // M_AXIS sink always ready
        m_axis_tready = 1'b1;

        // ---------------------------------------------------------------
        // Check 1: Reset exits without X on AXI-Lite outputs
        // ---------------------------------------------------------------
        aresetn = 1'b0;
        repeat (20) @(posedge aclk);
        aresetn = 1'b1;
        repeat (5) @(posedge aclk);

        $display("[C1] Reset released at %0t ns", $time);

        // Check AXI-Lite read channel not X after reset
        if (m_axi_arready === 1'bx || m_axi_arready === 1'bz) begin
            $display("FAIL [C1]: m_axi_arready is X/Z after reset");
            fail_count = fail_count + 1;
        end
        if (m_axi_rvalid === 1'bx || m_axi_rvalid === 1'bz) begin
            $display("FAIL [C1]: m_axi_rvalid is X/Z after reset");
            fail_count = fail_count + 1;
        end
        if (m_axi_awready === 1'bx || m_axi_awready === 1'bz) begin
            $display("FAIL [C1]: m_axi_awready is X/Z after reset");
            fail_count = fail_count + 1;
        end
        if (fail_count == 0) $display("PASS [C1]: AXI-Lite outputs not X after reset");

        // ---------------------------------------------------------------
        // Check 2: VERSION read returns expected constant
        // ---------------------------------------------------------------
        axi_read(ADDR_VERSION);
        if (axi_rd_data !== EXPECTED_VERSION) begin
            $display("FAIL [C2]: VERSION read = 0x%08X, expected 0x%08X",
                     axi_rd_data, EXPECTED_VERSION);
            fail_count = fail_count + 1;
        end else begin
            $display("PASS [C2]: VERSION = 0x%08X", axi_rd_data);
        end

        // ---------------------------------------------------------------
        // Check 3: CONTROL write sets enable; read-back confirms bit0=1
        // ---------------------------------------------------------------
        axi_write(ADDR_CONTROL, 32'h00000001);  // enable=1
        axi_read(ADDR_CONTROL);
        if (axi_rd_data[0] !== 1'b1) begin
            $display("FAIL [C3]: CONTROL[0] read-back = %0b, expected 1", axi_rd_data[0]);
            fail_count = fail_count + 1;
        end else begin
            $display("PASS [C3]: CONTROL enable=1 confirmed");
        end

        // ---------------------------------------------------------------
        // Check 4: S_AXIS tready not X after reset (DUT drives it)
        // ---------------------------------------------------------------
        repeat (3) @(posedge aclk);
        if (s_axis_tready === 1'bx || s_axis_tready === 1'bz) begin
            $display("FAIL [C4]: s_axis_tready is X/Z");
            fail_count = fail_count + 1;
        end else begin
            $display("PASS [C4]: s_axis_tready = %0b (not X)", s_axis_tready);
        end

        // ---------------------------------------------------------------
        // Check 5: M_AXIS tvalid not X
        // ---------------------------------------------------------------
        if (m_axis_tvalid === 1'bx || m_axis_tvalid === 1'bz) begin
            $display("FAIL [C5]: m_axis_tvalid is X/Z");
            fail_count = fail_count + 1;
        end else begin
            $display("PASS [C5]: m_axis_tvalid = %0b (not X)", m_axis_tvalid);
        end

        // ---------------------------------------------------------------
        // Check 6: Send 10 idle AXIS beats; verify no X propagation
        // ---------------------------------------------------------------
        $display("[C6] Sending 10 S_AXIS beats...");
        for (i = 0; i < 10; i = i + 1) begin
            s_axis_tdata  = {i[15:0], i[15:0]};
            s_axis_tvalid = 1'b1;
            s_axis_tlast  = (i == 9) ? 1'b1 : 1'b0;
            @(posedge aclk);
            // Check handshake signals are not X
            if (s_axis_tready === 1'bx || s_axis_tready === 1'bz) begin
                $display("FAIL [C6]: s_axis_tready X at beat %0d", i);
                fail_count = fail_count + 1;
            end
        end
        s_axis_tvalid = 1'b0;
        s_axis_tlast  = 1'b0;
        if (fail_count == 0)
            $display("PASS [C6]: 10 AXIS beats sent without X on tready");

        // ---------------------------------------------------------------
        // Check 7: STATUS register reads — not X
        // ---------------------------------------------------------------
        axi_read(ADDR_STATUS);
        if (axi_rd_data === 32'hxxxxxxxx) begin
            $display("FAIL [C7]: STATUS register is X");
            fail_count = fail_count + 1;
        end else begin
            $display("PASS [C7]: STATUS = 0x%08X (not X)", axi_rd_data);
        end

        // ---------------------------------------------------------------
        // Check 8: soft_reset_pulse via CONTROL[1] write
        // ---------------------------------------------------------------
        axi_write(ADDR_CONTROL, 32'h00000003);  // enable=1, soft_reset_pulse=1
        repeat (5) @(posedge aclk);
        axi_write(ADDR_CONTROL, 32'h00000001);  // enable=1
        $display("PASS [C8]: soft_reset_pulse write completed without hang");

        // ---------------------------------------------------------------
        // Final result
        // ---------------------------------------------------------------
        repeat (10) @(posedge aclk);

        if (fail_count == 0) begin
            $display("==============================================");
            $display("SANITY_GATE: PASS");
            $display("All %0d smoke checks passed.", 8);
            $display("Note: This is a compile/interface smoke test only.");
            $display("Official system PASS requires xsim + full golden compare.");
            $display("==============================================");
        end else begin
            $display("==============================================");
            $display("SANITY_GATE: FAIL  (%0d failure(s))", fail_count);
            $display("==============================================");
        end

        $finish;
    end

endmodule
